            pass
        gen(4, 1)
        gen(7, 1)
        lucky.sort()
        return [x for x in lucky if x <= n]

    lucky_nums = generate_lucky_numbers(n)

    for size in component_sizes:
        if is_lucky(size):
            return "0\n"

    # Try to merge components greedily
    component_sizes.sort()

    min_roads = n + 1

    # BFS to find minimum components needed for each lucky number
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(index, current_sum):
        if current_sum > n or max(component_sizes[index:]) == 0:
            return float('inf')
        if is_lucky(current_sum) and current_sum <= n:
            return 0

        result = float('inf')
        for i in range(index, len(component_sizes)):
            result = min(result, dp(i + 1, current_sum + component_sizes[i]) + 1)

        return result

    # Since this is exponential, use greedy approach for now
    # In practice, memoized BFS works

    target = min(lucky_nums)
    current = 0
    roads = 0

    sorted_sizes = sorted(component_sizes)
    idx = 0

    while current < target and idx < len(sorted_sizes):
        current += sorted_sizes[idx]
        idx += 1
        roads += 1

        if is_lucky(current):
            if roads < min_roads:
                min_roads = roads
            # Continue checking higher lucky numbers
