            # Calculate position based on cycle
            if cycle_mod == 0:
                rx, ry = x, y
            elif cycle_mod == 1:
                rx, ry = x + d, y - d
            elif cycle_mod == 2:
                rx, ry = x + d, y
            elif cycle_mod == 3:
                rx, ry = x, y + d

            # Check if position is within matrix bounds
            if 0 <= rx < N and 0 <= ry < M:
                # Blackout reaches (rx, ry) at time rx + ry
                # Transformer is at this position at time t + cycle_mod
                if time_tau == rx + ry:
                    grid[rx][ry] += e

    # DP to find minimum energy path from (0,0) to (N-1,M-1)
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = grid[0][0]

