MOD = 10**9 + 7

class Parser:
    def __init__(self, s: str):
        self.s = s
        self.idx = 0
        self.n = len(s)
        self.powers = [1]
        for _ in range(self.n):
            self.powers.append((self.powers[-1] * 10) % MOD

    def get_power(self, k: int) -> int:
        """Get 10^k mod MOD"""
        while len(self.powers) <= k:
            self.powers.append((self.powers[-1] * 10) % MOD)
        return self.powers[k]

    def peek(self) -> str:
        return self.s[self.idx] if self.idx < self.n else ''

    def consume(self, c: str) -> None:
        assert self.idx < self.n and self.s[self.idx] == c, f"Expected '{c}' at pos {self.idx}"
        self.idx += 1

    def parse_number(self) -> int:
        """Parse a number (posDigit followed by any digits)"""
        start = self.idx
        while self.idx < self.n and self.s[self.idx].isdigit():
            self.idx += 1
        val = int(self.s[start:self.idx])
        return val

    def get_number(self, l: int, r: int) -> int:
        """Concatenate all numbers from l to r, mod MOD"""
        if l > r:
            return 0

        ans = 0
        for x in range(l, r + 1):
            digits = len(str(x))
            ans = (ans * self.get_power(digits) + x) % MOD
        return ans

    def parse_expression(self) -> int:
        """expression ::= term | expression + term"""
        result = self.parse_term()
        while self.peek() == '+':
            self.consume('+')
            rhs = self.parse_term()
            result = self.concatenate(result, rhs)
        return result

    def parse_term(self) -> int:
        """term ::= number | number - number | number ( expression )"""
        left = self.parse_number()

        if self.peek() == '-':
            self.consume('-')
            right = self.parse_number()
            return self.get_number(left, right)
        elif self.peek() == '(':
            self.consume('(')
            inner = self.parse_expression()
            self.consume(')')
            return self.repeat(left, inner)
        else:
            return left

    def repeat(self, times: int, value: int) -> int:
        """Concatenate value, times times"""
        result = 0
        power = 1
        for _ in range(times):
            digits = len(str(value))
            power = (power * self.get_power(digits)) % MOD
            result = (result + value * power) % MOD
        return result

    def concatenate(self, left: int, right: int) -> int:
        """Concatenate left and right numbers"""
        digits = len(str(right))
        return (left * self.get_power(digits) + right) % MOD

    def solve(self) -> int:
        return self.parse_expression()

def solution(expr: str) -> str:
    return str(Parser(expr).solve())
