    # Count all pairs of 3-point combinations that form disjoint triangles.
    # Since checking all O(n^6) combinations is too slow, we iterate smarter.

    # For each possible first triangle (3 points from n):
    for tri1 in combinations(range(n), 3):
        set1 = set(tri1)
        remaining = [i for i in range(n) if i not in set1]

        if len(remaining) < 3:
