def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    priorities = []
    for i in range(n):
        priorities.append(list(map(int, lines[i+1].split())))

    # Get cells sorted by priority (ascending)
    cells = []
    for i in range(n):
        for j in range(m):
            cells.append((i, j, priorities[i][j]))
    cells.sort(key=lambda x: x[2])

    # Check if grid is valid
    def is_valid(grid):
        # All paths from (0,0) to (n-1,m-1) using only right and down moves
        # must form correct bracket sequences

        from functools import lru_cache

        @lru_cache(None)
        def check_path(r, c, balance):
            if balance < 0:
                return False
            if r == n - 1 and c == m - 1:
                return balance == 0

            result = False
            # Move right
            if c + 1 < m:
                char = grid[r][c + 1]
                new_bal = balance + (1 if char == '(' else -1)
                if new_bal >= 0:
                    if new_bal == 0 or (r == 0 and c + 1 < m):
                        result = result or check_path(r, c + 1, new_bal)

            # Move down
            if r + 1 < n:
                char = grid[r + 1][c]
                new_bal = balance + (1 if char == '(' else -1)
                if new_bal >= 0:
                    if new_bal == 0 or (r + 1 < n and c == 0):
                        result = result or check_path(r + 1, c, new_bal)

            return result

        return False

    return ""
