    cz = (a_dot*c[1]*b[0] + b_dot*a[1]*c[0] + c_dot*b[1]*a[0]) / cov

    return (cx, cy, cz, dist_sq([cx, cy, cz], p1))

def sphere_from_4(p1, p2, p3, p4):
    """Sphere with 4 non-coplanar points on boundary"""
    v1 = p2 - p1
    v2 = p3 - p1
    v3 = p4 - p1

    mat11 = dist_sq(p1, p2)
    mat12 = dot(v1, v1)
    mat13 = dot(v1, v2)
    mat14 = dot(v1, v3)

    mat21 = dist_sq(p1, p3)
    mat22 = dot(v2, v2)
    mat23 = dot(v2, v2 + v1)
    mat24 = dot(v2, v3 + v1)

    mat31 = dist_sq(p1, p4)
    mat32 = dot(v3, v3)
    mat33 = dot(v3, v3 + v1)
    mat34 = dot(v3, v3 + v2)

    return solve_linear_system(p1, p2, p3, p4)

def sphere_from_noncoplanar(p1, p2, p3, p4):
    """Find sphere from 4 non-coplanar points using linear system"""
    mat = [
        [p2[0]-p1[0], p2[1]-p1[1], p2[2]-p1[2]],
        [p3[0]-p1[0], p3[1]-p1[1], p3[2]-p1[2]],
        [p4[0]-p1[0], p4[1]-p1[1], p4[2]-p1[2]]
    ]

    det = mat[0][0]*(mat[1][1]*mat[2][2]-mat[1][2]*mat[2][1]) - mat[0][1]*(mat[1][0]*mat[2][2]-mat[1][2]*mat[2][0]) + mat[0][2]*(mat[1][0]*mat[2][1]-mat[1][1]*mat[2][0])

    if abs(det) < 1e-10:
        return (0.0, 0.0, 0.0, 0.0)

    dx = dist_sq([p1[0], p1[1], p1[2]], p1)
    dy = dist_sq([p1[0], p1[1], p1[2]], p2) - dist_sq([p1[0], p1[1], p1[2]], p1)
    dz = dist_sq([p1[0], p1[1], p1[2]], p3) - dist_sq([p1[0], p1[1], p1[2]], p1)
    dp = dist_sq([p1[0], p1[1], p1[2]], p4) - dist_sq([p1[0], p1[1], p1[2]], p1)

    # Solve using Cramer's rule
    cx = solve_det(mat, [dy, 0, 0]) / det
    cy = solve_det(mat, [0, dy, 0]) / det
    cz = solve_det(mat, [0, 0, dp]) / det

    return (cx, cy, cz, dist_sq([cx, cy, cz], p1))

def solve_det(mat, rhs):
    return mat[0][0]*(rhs[1]*mat[2][2]-rhs[2]*mat[2][1]) - mat[0][1]*(rhs[1]*mat[2][0]-rhs[2]*mat[1][0]) + mat[0][2]*(rhs[1]*mat[1][1]-rhs[2]*mat[2][1])

def in_sphere(point, center, r2):
    return dist_sq(point, center) <= r2 + 1e-8

def welzl(points, n):
    """Welzl's algorithm for minimum enclosing sphere"""
    random.shuffle(points[:n+1])

    def rec强制(nondp, R):
        if n == 0 or len(R) == 4:
            return sphere_from_0(nondp, R)

        i = nondp.index(next(p for p in nondp if True))

        if i < len(nondp):
            if in_sphere(nondp[i], R[0] if R else [0,0,0], R[3] if R else 0):
                return rec强制(nondp[:i] + nondp[i+1:], R)
            else:
                S = rec强制(nondp[:i] + nondp[i+1:], R + [nondp[i]])
                if in_sphere(nondp[i], S[0], S[3]):
                    return S
                else:
                    return rec强制(nondp[:i] + [nondp[i+1:]], R)

    return rec强制(range(len(points)), [])

def sphere_from_0(nondp, R):
    if not R:
        return (0.0, 0.0, 0.0, 0.0)
    if len(R) == 1:
        return sphere_from_1(R[0])
    if len(R) == 2:
        return sphere_from_2(R[0], R[1])
    if len(R) == 3:
        return sphere_from_3(R[0], R[1], R[2])
    if len(R) == 4:
        return sphere_from_4(R[0], R[1], R[2], R[3])

    return (0.0, 0.0, 0.0, 0.0)

def sphere_from_1(p):
    return (p[0], p[1], p[2], 0.0)

def solve_linear_system(p1, p2, p3, p4):
    """Find minimum enclosing sphere that has p1, p2, p3, p4 on boundary"""
    det = solve_det(mat, rhs)
    if abs(det) < 1e-10:
        return (0.0, 0.0, 0.0, 0.0)

    return (p[0], p[1], p[2], dist_sq([p[0], p[1], p[2]], p1))

def main_solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])

    points = []
    for i in range(1, n+1):
        parts = lines[i].split()
        x, y, z = float(parts[0]), float(parts[1]), float(parts[2])
        points.append([x, y, z])

    random.seed(42)

    m = len(points)
    S = welzl(points, m)

    return f"{S[0]:.10f} {S[1]:.10f} {S[2]:.10f}"
