        def get_canonical(s):
            """Get the lexicographically smallest among all equivalent strings."""
            variants = {
                s, 
                s[::-1],  # reversed
                ''.join('1' if c == '0' else '0' for c in s),  # color swapped
                ''.join('0' if c == '1' else '1' for c in s[::-1])  # reversed + color swapped
            }
            return min(variants)

        def get_canonical_strings(n):
            """Get all unique canonical strings for length n."""
            all_strings = [f'{i:0{n}b}' for i in range(1 << n)]
            canonical_set = set()
            canonical_list = []

            for s in all_strings:
                c = get_canonical(s)
                if c not in canonical_set:
                    canonical_set.add(c)
                    canonical_list.append(c)

            canonical_list.sort()
            return canonical_list

        try:
            result = get_canonical_strings(n)
            if 1 <= k <= len(result):
                return result[k-1] + '\n'
            else:
                return '-1\n'
        except MemoryError:
            return '-1\n'
    except:
        return '-1\n'


